-- Synthetic pharmaceutical SQL practice database (MySQL 8.0+)
-- All names and records are fictional and are not Bayer internal data.

DROP DATABASE IF EXISTS pharma_steward_practice;
CREATE DATABASE pharma_steward_practice;
USE pharma_steward_practice;

CREATE TABLE countries (
  country_code CHAR(2) PRIMARY KEY,
  country_name VARCHAR(60) NOT NULL,
  region VARCHAR(40) NOT NULL
);

CREATE TABLE products (
  product_id INT PRIMARY KEY,
  product_name VARCHAR(80) NOT NULL,
  therapeutic_area VARCHAR(60) NOT NULL,
  dosage_form VARCHAR(40) NOT NULL,
  rx_otc ENUM('Rx','OTC') NOT NULL,
  launch_date DATE NOT NULL,
  product_status ENUM('Active','Discontinued') NOT NULL
);

CREATE TABLE product_registrations (
  registration_id INT PRIMARY KEY,
  product_id INT NOT NULL,
  country_code CHAR(2) NOT NULL,
  registration_status ENUM('Approved','Pending','Expired') NOT NULL,
  approval_date DATE NULL,
  expiry_date DATE NULL,
  UNIQUE KEY uq_product_country (product_id, country_code),
  FOREIGN KEY (product_id) REFERENCES products(product_id),
  FOREIGN KEY (country_code) REFERENCES countries(country_code)
);

CREATE TABLE customers (
  customer_id INT PRIMARY KEY,
  customer_name VARCHAR(120) NOT NULL,
  customer_type ENUM('Hospital','Pharmacy','Distributor','Clinic') NOT NULL,
  country_code CHAR(2) NOT NULL,
  customer_status ENUM('Active','Inactive') NOT NULL,
  created_date DATE NOT NULL,
  FOREIGN KEY (country_code) REFERENCES countries(country_code)
);

CREATE TABLE batches (
  batch_id INT PRIMARY KEY,
  product_id INT NOT NULL,
  lot_number VARCHAR(30) NOT NULL UNIQUE,
  manufacture_date DATE NOT NULL,
  expiry_date DATE NOT NULL,
  batch_status ENUM('Released','Quarantined','Recalled') NOT NULL,
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE sales_orders (
  order_id INT PRIMARY KEY,
  customer_id INT NOT NULL,
  order_date DATE NOT NULL,
  order_status ENUM('Delivered','Shipped','Cancelled','Pending') NOT NULL,
  delivery_date DATE NULL,
  currency CHAR(3) NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE order_items (
  order_item_id INT PRIMARY KEY,
  order_id INT NOT NULL,
  product_id INT NOT NULL,
  batch_id INT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL,
  discount_pct DECIMAL(5,2) NOT NULL DEFAULT 0,
  FOREIGN KEY (order_id) REFERENCES sales_orders(order_id),
  FOREIGN KEY (product_id) REFERENCES products(product_id),
  FOREIGN KEY (batch_id) REFERENCES batches(batch_id)
);

-- Deliberately unconstrained staging data for data-quality exercises.
CREATE TABLE staging_product_updates (
  staging_id INT PRIMARY KEY,
  source_product_id VARCHAR(20) NULL,
  source_product_name VARCHAR(100) NULL,
  therapeutic_area VARCHAR(60) NULL,
  country_code VARCHAR(10) NULL,
  source_status VARCHAR(30) NULL,
  loaded_at DATETIME NOT NULL
);

